CREATE TABLE IF NOT EXISTS public.respawns ( id VARCHAR(50) PRIMARY KEY, name VARCHAR(255) NOT NULL, category VARCHAR(100), created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL ); CREATE TABLE IF NOT EXISTS public.hunting_claims ( id SERIAL PRIMARY KEY, respawn_id VARCHAR(50) REFERENCES public.respawns(id) ON DELETE CASCADE, character_name VARCHAR(255) NOT NULL, ts3_uid VARCHAR(255), discord_id VARCHAR(255), web_user_id UUID, claimed_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL, status VARCHAR(50) DEFAULT 'ACTIVE' ); CREATE TABLE IF NOT EXISTS public.hunting_queues ( id SERIAL PRIMARY KEY, respawn_id VARCHAR(50) REFERENCES public.respawns(id) ON DELETE CASCADE, character_name VARCHAR(255) NOT NULL, ts3_uid VARCHAR(255), discord_id VARCHAR(255), web_user_id UUID, joined_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL, status VARCHAR(50) DEFAULT 'WAITING' );
